function fewestPresses(n: number): number {
  const best = new Array(n + 1).fill(Infinity);
  best[1] = 0;
  for (let i = 2; i <= n; i++) {
    for (let d = 1; d < i; d++) {
      if (i % d === 0) best[i] = Math.min(best[i], best[d] + i / d);
    }
  }
  return best[n];
}

